import{_ as e,c as r,o as t,a0 as _}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Mentale spilløvelser","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/no/exercise-worksheets.md","filePath":"public/downloads/no/exercise-worksheets.md"}');const l=e({name:"public/downloads/no/exercise-worksheets.md"},[["render",function(e,i,l,n,a,s){return t(),r("div",null,[...i[0]||(i[0]=[_('<h1 id="mentale-spilløvelser" tabindex="-1">Mentale spilløvelser <a class="header-anchor" href="#mentale-spilløvelser" aria-label="Permalink to &quot;Mentale spilløvelser&quot;">​</a></h1><p><strong>Pétanque Academy - Praktiske øvelser</strong></p><hr><h2 id="øvelse-1-refleksjon-av-strømningstilstand" tabindex="-1">Øvelse 1: Refleksjon av strømningstilstand <a class="header-anchor" href="#øvelse-1-refleksjon-av-strømningstilstand" aria-label="Permalink to &quot;Øvelse 1: Refleksjon av strømningstilstand&quot;">​</a></h2><h3 id="nar-har-du-opplevd-flyt" tabindex="-1">Når har du opplevd flyt? <a class="header-anchor" href="#nar-har-du-opplevd-flyt" aria-label="Permalink to &quot;Når har du opplevd flyt?&quot;">​</a></h3><p>Tenk på en gang du spilte din beste petanque:</p><p><strong>Beskriv situasjonen:</strong></p><ul><li>Hvilken turnering/kamp var det?</li><li>Hva var betingelsene?</li><li>Hvem spilte du med?</li></ul><hr><hr><p><strong>Hvordan føltes det?</strong></p><ul><li>Hva var din mentale tilstand?</li><li>Hvordan føltes tiden?</li><li>Hva tenkte du (eller tenkte ikke)?</li></ul><hr><hr><p><strong>Hva hjalp deg med å komme dit?</strong></p><ul><li>Hva gjorde du før kampen?</li><li>Hva var annerledes med den dagen?</li><li>Kan du gjenskape noen av disse forholdene?</li></ul><hr><hr><hr><h2 id="øvelse-2-indre-kritiker-inventar" tabindex="-1">Øvelse 2: Indre kritiker-inventar <a class="header-anchor" href="#øvelse-2-indre-kritiker-inventar" aria-label="Permalink to &quot;Øvelse 2: Indre kritiker-inventar&quot;">​</a></h2><h3 id="identifiser-din-indre-kritiker" tabindex="-1">Identifiser din indre kritiker <a class="header-anchor" href="#identifiser-din-indre-kritiker" aria-label="Permalink to &quot;Identifiser din indre kritiker&quot;">​</a></h3><p><strong>Hva sier din indre kritiker?</strong></p><p>Nevn 3–5 vanlige kritiske tanker du har under konkurranser:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>Når dukker den opp?</strong></p><ul><li>Etter feil? □</li><li>Før viktige bilder? □</li><li>Når man spiller mot sterke motstandere? □</li><li>Når lagkameratene ser på? □</li><li>Annet: ______________________________________________</li></ul><hr><h2 id="øvelse-3-øvelse-pa-omformulering" tabindex="-1">Øvelse 3: Øvelse på omformulering <a class="header-anchor" href="#øvelse-3-øvelse-pa-omformulering" aria-label="Permalink to &quot;Øvelse 3: Øvelse på omformulering&quot;">​</a></h2><h3 id="forvandle-kritiker-til-coach" tabindex="-1">Forvandle kritiker til coach <a class="header-anchor" href="#forvandle-kritiker-til-coach" aria-label="Permalink to &quot;Forvandle kritiker til coach&quot;">​</a></h3><p><strong>For hver indre kritiker-tanke, skriv en indre coach-omformulering:</strong></p><table tabindex="0"><thead><tr><th>Indre kritiker</th><th>Indre coach</th></tr></thead><tbody><tr><td>Eksempel: «Jeg roter alltid til under press»</td><td>«Jeg har lykkes under press før, jeg kan gjøre det igjen»</td></tr><tr><td>1. ________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. ________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Øv på å si disse høyt</strong></p><hr><h2 id="øvelse-4-utforming-av-rutine-før-opptak" tabindex="-1">Øvelse 4: Utforming av rutine før opptak <a class="header-anchor" href="#øvelse-4-utforming-av-rutine-før-opptak" aria-label="Permalink to &quot;Øvelse 4: Utforming av rutine før opptak&quot;">​</a></h2><h3 id="lag-din-personlige-rutine" tabindex="-1">Lag din personlige rutine <a class="header-anchor" href="#lag-din-personlige-rutine" aria-label="Permalink to &quot;Lag din personlige rutine&quot;">​</a></h3><p>Lag en 4-trinns rutine før bruk som fungerer for deg:</p><p><strong>Trinn 1: Visualiser</strong></p><ul><li>Hva vil du visualisere, helt konkret?</li><li>Hvor lenge (2–3 sekunder)?</li></ul><hr><p><strong>Trinn 2: Pust</strong></p><ul><li>Ett dypt åndedrag eller tre?</li><li>Noe spesifikt mønster?</li></ul><hr><p><strong>Trinn 3: Anker</strong></p><ul><li>Hvilket fysisk anker vil du bruke?</li><li>Berøringsboule? Spesifikk holdning?</li></ul><hr><p><strong>Trinn 4: Utfør</strong></p><ul><li>Hva er din mentale signal?</li><li>«Tillit» / «Flyt» / «Gå»?</li></ul><hr><p><strong>Øv på denne rutinen 10 ganger i dag</strong></p><hr><h2 id="øvelse-5-trykkutløsere" tabindex="-1">Øvelse 5: Trykkutløsere <a class="header-anchor" href="#øvelse-5-trykkutløsere" aria-label="Permalink to &quot;Øvelse 5: Trykkutløsere&quot;">​</a></h2><h3 id="identifiser-trykkpunktene-dine" tabindex="-1">Identifiser trykkpunktene dine <a class="header-anchor" href="#identifiser-trykkpunktene-dine" aria-label="Permalink to &quot;Identifiser trykkpunktene dine&quot;">​</a></h3><p><strong>Hvilke situasjoner skaper press for deg?</strong></p><p>Vurder hver fra 1 (ikke noe press) til 10 (ekstremt press):</p><ul><li>Spille mot sterke motstandere: ___/10</li><li>Viktige turneringskamper: ___/10</li><li>Uavgjort, siste skudd: ___/10</li><li>Etter å ha gjort en feil: ___/10</li><li>Når lagkamerater ser på: ___/10</li><li>Når jeg spiller dårlig: ___/10</li><li>Annet: ___________________________ ___/10</li></ul><p><strong>For din høyest rangerte trigger:</strong></p><p>Hvilke fysiske sanseinntrykk merker du?</p><hr><p>Hvilke tanker dukker opp?</p><hr><p>Hvilken teknikk vil du bruke?</p><ul><li>[ ] 3-pust tilbakestilling</li><li>[ ] Rutine før inntak</li><li>[ ] Omformulering</li><li>[ ] Annet: _____________________</li></ul><hr><h2 id="øvelse-6-øvelse-pa-modusbytte" tabindex="-1">Øvelse 6: Øvelse på modusbytte <a class="header-anchor" href="#øvelse-6-øvelse-pa-modusbytte" aria-label="Permalink to &quot;Øvelse 6: Øvelse på modusbytte&quot;">​</a></h2><h3 id="planlegging-vs-utførelse" tabindex="-1">Planlegging vs. utførelse <a class="header-anchor" href="#planlegging-vs-utførelse" aria-label="Permalink to &quot;Planlegging vs. utførelse&quot;">​</a></h3><p><strong>Øv på bryteren:</strong></p><p><strong>Planleggingsfase (før opptak):</strong></p><ul><li>Hva trenger jeg å analysere?</li><li>Hva er strategien min?</li><li>Hvilket skudd skal jeg velge?</li></ul><p><strong>Utførelsesfase (under opptaket):</strong></p><ul><li>Tøm tankene dine</li><li>Stol på kroppen din</li><li>La det skje</li></ul><p><strong>Øvingsøvelse:</strong></p><p>Ta 5 øvingsskudd. For hvert:</p><ol><li>Bruk 10 sekunder i planleggingsmodus (analyser, avgjør)</li><li>Ta 3 åndedrag for å bytte modus</li><li>Utfør i flytmodus (ingen tenking)</li></ol><p><strong>Speilbilde:</strong></p><ul><li>Kunne du føle forskjellen mellom modusene?</li><li>Var bryteren tydelig?</li><li>Hvilken modus er vanskeligst for deg?</li></ul><hr><hr><hr><h2 id="øvelse-7-ukentlig-øvingsplan" tabindex="-1">Øvelse 7: Ukentlig øvingsplan <a class="header-anchor" href="#øvelse-7-ukentlig-øvingsplan" aria-label="Permalink to &quot;Øvelse 7: Ukentlig øvingsplan&quot;">​</a></h2><h3 id="denne-ukens-fokus" tabindex="-1">Denne ukens fokus <a class="header-anchor" href="#denne-ukens-fokus" aria-label="Permalink to &quot;Denne ukens fokus&quot;">​</a></h3><p><strong>Velg ÉN teknikk å øve på:</strong></p><ul><li>[] 3-Åndrestilling etter hver feil</li><li>[] Rutine før skudd på hvert kast</li><li>[] Omformuler én indre kritiker-tanke per økt</li><li>[ ] Bytte av øvingsmodus</li></ul><p><strong>Daglig trening:</strong></p><table tabindex="0"><thead><tr><th>Dag</th><th>Øvingsaktivitet</th><th>Varighet</th><th>Notater</th></tr></thead><tbody><tr><td>man</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>tirs</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Ons</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>tors</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>fre</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Lørdag</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sol</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="øvelse-8-fremdriftssporing" tabindex="-1">Øvelse 8: Fremdriftssporing <a class="header-anchor" href="#øvelse-8-fremdriftssporing" aria-label="Permalink to &quot;Øvelse 8: Fremdriftssporing&quot;">​</a></h2><h3 id="refleksjon-ved-ukens-slutt" tabindex="-1">Refleksjon ved ukens slutt <a class="header-anchor" href="#refleksjon-ved-ukens-slutt" aria-label="Permalink to &quot;Refleksjon ved ukens slutt&quot;">​</a></h3><p><strong>Hva øvde du på denne uken?</strong></p><hr><p><strong>Hva la du merke til?</strong></p><hr><hr><p><strong>Hva fungerte bra?</strong></p><hr><hr><p><strong>Hva var utfordrende?</strong></p><hr><hr><p><strong>Hva skal du fortsette med neste uke?</strong></p><hr><hr><p><strong>Hva vil du justere?</strong></p><hr><hr><hr><h2 id="neste-trinn" tabindex="-1">Neste trinn <a class="header-anchor" href="#neste-trinn" aria-label="Permalink to &quot;Neste trinn&quot;">​</a></h2><h3 id="fortsett-utviklingen-din" tabindex="-1">Fortsett utviklingen din <a class="header-anchor" href="#fortsett-utviklingen-din" aria-label="Permalink to &quot;Fortsett utviklingen din&quot;">​</a></h3><p><strong>Ressurser på carreau.app:</strong></p><ul><li>Målmal – Strukturer din langsiktige utvikling</li><li>Dagbokmal – Spor daglig fremgang</li><li>Sonen – Dykk dypt inn i flyttilstander</li><li>Mental styrke - Avansert pressmestring</li></ul><p><strong>Fortsett å øve:</strong></p><ul><li>Mentale ferdigheter trenger jevnlig trening</li><li>Start i det små, bygg gradvis</li><li>Spor fremgangen din</li><li>Feir forbedringer</li></ul><hr><p><em>Pétanque Academy - Elitespillerutvikling</em><em>carreau.app</em></p>',113)])])}]]);export{i as __pageData,l as default};
